export function CommandGrid(n,s){const a="All"===s?n:n.filter(n=>n.service===s);if(0===a.length)return'<div class="no-results">No commands found for this service.</div>';return`\n        <div class="command-grid">\n            ${a.map(n=>`\n        <div class="command-card" data-service="${n.service}">\n            <div class="command-service-badge" data-service="${n.service}">${n.service}</div>\n            <h4 class="command-name">${n.name}</h4>\n            <div class="command-meta">\n                <span class="command-hq">HQ: ${n.hq}</span>\n                <span class="command-type">${n.type}</span>\n            </div>\n            <p class="command-responsibility">${n.responsibility}</p>\n        </div>\n    `).join("")}\n        </div>\n    `}